sp_widget.client_script:
function($scope,$rootScope) {
	/* widget controller */
	var c = this;
	// 選択したレコードのフィールド値をサーバーから取得して、表示
	$rootScope.$on('selectNote', function(event,data) { 
		// サーバースクリプトを呼び出しカスタム入力を渡す
		// Promiseを返す。サーバーからレスポンスを受信するとthen()関数を実行
		c.server.get({
			// getNoteとnoteIDをサーバーに渡す
			action: 'getNote',
			noteID: $rootScope.noteID
			// サーバーからレスポンスを受け取った後に実行される
		}).then(function(r) {
			c.data.title = r.data.note.title;
			c.data.note = r.data.note.note;
			c.data.noteID = r.data.note.sys_id;
		});
	});
// HTMLのng-changeで実行される関数
	c.updateNote = function(updateType) {
		c.server.get({
			action: 'updateNote',
			noteID: c.data.noteID,
			noteBody: c.data.note,
			noteTitle: c.data.title
		}).then(function(r) {
		});
	}
}

sp_widget.script:
// クライアント スクリプトから呼び出されたgetNoteアクションに応答するロジック
(function() {
	/* populate the 'data' object */
	// 入力オブジェクトは、クライアント スクリプトのコントローラーから受信したデータオブジェクト
	if (input && input.noteID) {
		var note = new GlideRecord('x_snc_createnotes_note');
		if (note.get(input.noteID)) {
			if (input.action == 'getNote') {
				// クライアントに返すための空のオブジェクトを用意
				data.note = {};
				// gliderecordオブジェクトのnoteから指定フィールドをdata.noteにコピー
				// 指定されたnoteの「タイトル」「本文」「sys_id」を取り出して、クライアントに渡す準備
				$sp.getRecordValues(data.note, note, "title, note, sys_id");
			}
			// クライアントから受け取った新しい値を使用してデータベース内Notesレコード更新
			else if (input.action == 'updateNote') { 
				// inputオブジェクトはクライアントから受信される
				note.title = input.noteTitle; 
				note.note = input.noteBody; 
				// 既存レコードの新しい値をデータベースに書き込む
				note.update(); 
			}
		}
	}
})();
